// Общие шаги для смет (#ca1a27 проверки при пустом Save, #a96197 окно Send не сохраняет черновик; план specs/estimates.md).
// ca1a27 — Pre-Prod, preprod-ttp (TTP Test Locks), EN; a96197 — prod, admin, компания «test» (startInTest), EN.
// Не сверено с сайтом при записи: тексты ошибок — по скриншоту ca1a27-both-errors-desktop.png («Please add at least one item»)
// и комментарию программиста («Please select a client»); окно «Select Client» открывается само при New Estimate.
import { expect, Page, Request } from '@playwright/test';
import { createNew } from '../pricebook/pricebook-helpers';

export { createNew };
export const NO_CLIENT = 'Please select a client';
export const NO_ITEMS = 'Please add at least one item';

/** Запросы записи сметы (POST/PATCH/PUT на URL с assessment) — страница не должна ничего сохранять. */
export function watchAssessmentWrites(page: Page): string[] {
  const writes: string[] = [];
  page.on('request', (r: Request) => {
    if (['POST', 'PATCH', 'PUT'].includes(r.method()) && /assessment/i.test(r.url()) && ['fetch', 'xhr'].includes(r.resourceType())) {
      writes.push(`${r.method()} ${r.url()}`);
    }
  });
  return writes;
}

/** Системные окна (alert/confirm) — их быть не должно. */
export function watchDialogs(page: Page): string[] {
  const seen: string[] = [];
  page.on('dialog', (d) => { seen.push(`${d.type()}: ${d.message()}`); d.dismiss().catch(() => {}); });
  return seen;
}

/** Create new → New Estimate; окно выбора клиента закрыто (клиент не выбран). */
export async function openEmptyNewEstimate(page: Page) {
  await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
  await createNew(page, 'New Estimate');
  await page.waitForURL(/\/EstimateCreation/);
  const picker = page.getByRole('dialog', { name: 'Select Client' });
  if (await picker.isVisible()) await page.keyboard.press('Escape');
  await expect(picker).toBeHidden();
  await expect(page.getByRole('button', { name: 'Save', exact: true }).filter({ visible: true }).first()).toBeVisible();
}
